"""Root-owned RuntimeShell integration. Generated by the player-command agent.

All changes are assembled in memory and required anchors are checked before a
single write. Run with --apply to write RuntimeShell.cpp; default is dry-run.
Do not run concurrently with another writer of RuntimeShell.cpp.
"""
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[3]
path = root / "src" / "runtime" / "host" / "RuntimeShell.cpp"
baseline = path.read_bytes()
had_bom = baseline.startswith(b'\xef\xbb\xbf')
newline = '\r\n' if b'\r\n' in baseline else '\n'
source = baseline.decode('utf-8-sig').replace('\r\n', '\n')
if '#include "ui/input/RuntimePlayerCommands.h"' in source:
    raise SystemExit("player command integration already present; do not apply twice")

def once(old, new):
    global source
    if source.count(old) != 1:
        raise RuntimeError(f"expected one anchor ({source.count(old)} found): {old[:160]}")
    source = source.replace(old, new, 1)

def section(start, end, transform):
    global source
    a = source.index(start)
    b = source.index(end, a + len(start))
    source = source[:a] + transform(source[a:b]) + source[b:]

def local_once(text, old, new):
    if text.count(old) != 1:
        raise RuntimeError(f"local anchor mismatch ({text.count(old)}): {old[:140]}")
    return text.replace(old, new, 1)

