def wire_apply(text):
    target_start = text.index('            if constexpr (std::is_same_v<\n                    Body,\n                    RuntimeMultiplayerGameplayTargetOrderCommand>) {')
    stop_start = text.index('            } else if constexpr (std::is_same_v<\n                    Body,\n                    RuntimeMultiplayerGameplayStopCommand>) {', target_start)
    text = text[:target_start] + '''            if constexpr (std::is_same_v<
                    Body,
                    RuntimeMultiplayerGameplayTargetOrderCommand>) {
                return applyRuntimePlayerTargetOrder(state, owner, body);
''' + text[stop_start:]
    for kind in ('Stop', 'Guard', 'Scatter', 'SecondaryAction'):
        anchor = f'                    RuntimeMultiplayerGameplay{kind}Command>) {{'
        text = local_once(text, anchor, anchor + '\n                state.playerCommands.cancel(body.objectIds);')
    additions = '''            } else if constexpr (std::is_same_v<Body,
                    RuntimeMultiplayerGameplaySetPrimaryFactoryCommand>) {
                return applyRuntimePlayerPrimaryFactory(state, owner, body.objectId);
            } else if constexpr (std::is_same_v<Body,
                    RuntimeMultiplayerGameplaySetRallyPointCommand>) {
                return applyRuntimePlayerRallyPoint(state, owner, body.objectId, body.cell);
'''
    return local_once(text, fire_else, additions + fire_else)
section('bool applyRuntimeMultiplayerGameplayCommand(', '\nbool ', wire_apply)
