print(f"Prepared {path}: {len(source)} characters")
if '--apply' in sys.argv:
    if path.read_bytes() != baseline:
        raise SystemExit('RuntimeShell.cpp changed during integration; retry against the new source')
    output = source.replace('\n', newline).encode('utf-8')
    if had_bom:
        output = b'\xef\xbb\xbf' + output
    path.write_bytes(output)
    print('Applied player command wiring.')
else:
    print('Dry run only; pass --apply to write.')
